    public static IReadOnlyList<string> Languages => SecureConnectionStrings.Languages;
    public static IReadOnlyCollection<string> Keys => Text.Keys;
    public static bool Contains(string key) => Text.ContainsKey(key) || Aliases.ContainsKey(key);
    public static string Get(string key) => GetForLanguage(Strings.Language, key);
    public static string GetForLanguage(string language, string key)
    { var index = Languages.ToList().IndexOf(language); if (Aliases.TryGetValue(key, out var alias)) key = alias; return (Text.TryGetValue(key, out var values) ? values : Text["InvalidProfile"])[index < 0 ? 1 : index]; }
    public static string Verification(BusDataSecurity value) => Get(value switch
    { BusDataSecurity.IncomingAuthenticated => "Authenticated", BusDataSecurity.IncomingAuthenticatedAndConfidential => "Confidential", _ => "TelegramUnverified" });
